package com.smartfitagent.mvc;
import java.nio.charset.StandardCharsets; import java.util.*;
public record Response(int status, byte[] body, Map<String,String> headers){ public static Response json(String s){return new Response(200,s.getBytes(StandardCharsets.UTF_8),Map.of("Content-Type","application/json; charset=utf-8","Cache-Control","no-store"));} public static Response html(String s){return new Response(200,s.getBytes(StandardCharsets.UTF_8),Map.of("Content-Type","text/html; charset=utf-8"));} public static Response bytes(byte[] b,String type){return new Response(200,b,Map.of("Content-Type",type));} public static Response redirect(String loc){return new Response(302,new byte[0],Map.of("Location",loc));} public static Response notFound(String p){return new Response(404,("404 "+p).getBytes(StandardCharsets.UTF_8),Map.of("Content-Type","text/plain; charset=utf-8"));} }
